import json, os, dlt
LAKE2 = os.path.abspath("./_lake2")

RECS = [
  {"Id":1,"Nested":{"a":1,"b":{"c":2}},"Arr":[{"x":1},{"x":2}],"Only1":"present"},
  {"Id":2,"Nested":{"a":9,"b":{"c":8}},"Arr":[],"NewFieldLater":True},
]

@dlt.resource(name="probe_a_jsonstr", write_disposition="append")
def a():
    for r in RECS: yield {"payload": json.dumps(r), "_src_entity":"Probe"}

@dlt.resource(name="probe_b_jsonhint", write_disposition="append",
              columns={"payload":{"data_type":"json"}})
def b():
    for r in RECS: yield {"payload": r, "_src_entity":"Probe"}

@dlt.resource(name="probe_c_nest0", write_disposition="append", max_table_nesting=0)
def c():
    for r in RECS: yield r

p = dlt.pipeline(
    pipeline_name="probe_raw",
    destination=dlt.destinations.filesystem(
        bucket_url=LAKE2,
        enable_dataset_name_normalization=False,
    ),
    dataset_name="das__raw",
)
print(p.run([a(), b(), c()], loader_file_format="parquet"))
print("=== TABLES CREATED ===", sorted(p.default_schema.tables.keys()))
for t in sorted(p.default_schema.tables.keys()):
    if t.startswith("probe"):
        print(f"--- {t} ---", {k: v.get('data_type') for k, v in p.default_schema.tables[t]["columns"].items()})
PYEOF
